-- 527: Original BrillaPrep NSMQ subj_nsmq_biology round_one beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_527_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_527_guard;
INSERT INTO _migration_527_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_r1_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_bio_genetics' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a monohybrid cross between two heterozygous parents (Tt × Tt), what fraction of the offspring is expected to show the recessive phenotype?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 1/4","B. 1/2","C. 3/4","D. All of them"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The Punnett square for Tt × Tt gives genotypes 1 TT : 2 Tt : 1 tt. Only the tt genotype shows the recessive phenotype, which is 1 of 4 boxes, so the expected fraction is 1/4 (25%). The 3/4 figure is the dominant-phenotype fraction.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_r1_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_527_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_r1_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_bio_cells' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which organelle is the main site of aerobic respiration in a eukaryotic cell?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Ribosome","B. Mitochondrion","C. Chloroplast","D. Nucleus"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Aerobic respiration occurs in the mitochondria, whose folded inner membranes (cristae) carry the enzymes that release energy from glucose as ATP. Ribosomes make proteins, chloroplasts photosynthesise, and the nucleus stores DNA.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_r1_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_527_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_r1_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_bio_ecology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a food chain, an organism that feeds on primary consumers is called a' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Producer","B. Herbivore","C. Secondary consumer","D. Decomposer"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Primary consumers are herbivores feeding on producers, so the next trophic level — carnivores or omnivores eating those herbivores — is the secondary consumer level. Decomposers break down dead material from all levels.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_r1_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_527_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_r1_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_bio_biochemistry' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'At approximately what temperature do most enzymes in the human body work fastest?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 0 °C","B. 20 °C","C. 100 °C","D. 37 °C"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Human enzymes have an optimum near normal body temperature, about 37 °C: kinetic energy and collision rates are high enough without damaging the enzyme’s shape. Well above this the enzyme denatures; near 0 °C activity almost stops.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_r1_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_bio_r1_b002_001', 'topic_nsmq_bio_genetics', 'subj_nsmq_biology', 'exam_nsmq', NULL, NULL, 'In a monohybrid cross between two heterozygous parents (Tt × Tt), what fraction of the offspring is expected to show the recessive phenotype?', 'multiple_choice', 'round_one', '["A. 1/4","B. 1/2","C. 3/4","D. All of them"]', 'A', 'The Punnett square for Tt × Tt gives genotypes 1 TT : 2 Tt : 1 tt. Only the tt genotype shows the recessive phenotype, which is 1 of 4 boxes, so the expected fraction is 1/4 (25%). The 3/4 figure is the dominant-phenotype fraction.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
