INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_bio_r1_b002_003', 'topic_nsmq_bio_ecology', 'subj_nsmq_biology', 'exam_nsmq', NULL, NULL, 'In a food chain, an organism that feeds on primary consumers is called a', 'multiple_choice', 'round_one', '["A. Producer","B. Herbivore","C. Secondary consumer","D. Decomposer"]', 'C', 'Primary consumers are herbivores feeding on producers, so the next trophic level — carnivores or omnivores eating those herbivores — is the secondary consumer level. Decomposers break down dead material from all levels.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_bio_r1_b002_004', 'topic_nsmq_bio_biochemistry', 'subj_nsmq_biology', 'exam_nsmq', NULL, NULL, 'At approximately what temperature do most enzymes in the human body work fastest?', 'multiple_choice', 'round_one', '["A. 0 °C","B. 20 °C","C. 100 °C","D. 37 °C"]', 'D', 'Human enzymes have an optimum near normal body temperature, about 37 °C: kinetic energy and collision rates are high enough without damaging the enzyme’s shape. Well above this the enzyme denatures; near 0 °C activity almost stops.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
